// ISSUE-1303 [Google Demand Gen video CREATE fix] — the square Mingla logo,
// embedded as a base64 PNG constant for the Demand Gen video responsive ad's
// REQUIRED logo_images asset.
//
// WHY THIS MODULE EXISTS (read before "simplifying" to a runtime URL fetch):
// A demandGenVideoResponsiveAd REQUIRES >=1 square (1:1) logo image asset — the
// #997-D2 "logoImages is OPTIONAL" assumption was live-DISPROVEN against
// Google's real validate (collectionSizeError: TOO_FEW @ ...logo_images,
// requestId BUKsXAWQRVlGHBMSIafe4g). This is NOT a secret — it is the PUBLIC
// Mingla app icon (packages/brand-assets/mingla-app-icon-500.png, 500x500 1:1,
// sha256 bfa1260dc23f55e59716c726a90cfaf393ae92cb81013769cdc07415b04eb986),
// the exact bytes forensics validated to HTTP 200 on Google Ads v24 AND v25.
//
// THE RULE: embed the bytes (self-contained inside the edge deploy set) — do
// NOT fetch a logo URL at create time (no live URL currently serves a SQUARE
// logo, and a runtime fetch can fail exactly when a create must succeed).
// Google dedupes identical image bytes, so per-create inline creation does not
// proliferate assets. Base64 is the JSON wire encoding for the Google Ads
// Asset.image_asset `data` bytes field.

/** SHA-256 of the decoded PNG bytes — asserts the constant was not corrupted. */
export const MINGLA_SQUARE_LOGO_PNG_SHA256 =
  "bfa1260dc23f55e59716c726a90cfaf393ae92cb81013769cdc07415b04eb986";

/** Base64 of packages/brand-assets/mingla-app-icon-500.png (500x500 1:1 PNG). */
export const MINGLA_SQUARE_LOGO_PNG_BASE64 =
  "";
